                var loc = new Location { Page = chunkDoc.Pages[startPage] };

                var bm = new BookmarkItem(Path.GetFileNameWithoutExtension(path), loc);

                chunkDoc.Bookmarks.Add(bm);

            }

            string output = Path.Combine(

